// Asserts that two 3D arrays have equal values within a tolerance
void helper_assert_3d_array_equal(struct kohonen_array_3d *arr1, struct kohonen_array_3d *arr2, double tolerance) {
    assert(arr1->dim1 == arr2->dim1 && arr1->dim2 == arr2->dim2 && arr1->dim3 == arr2->dim3);
    for (int x = 0; x < arr1->dim1; x++) {
        for (int y = 0; y < arr1->dim2; y++) {
